temp_python_code:
候補者 = "ABC"
投票結果 = "C,B,A,B,B,B,C,B,B,A,C,B,C,B,B"
候補者と投票結果を分離する = {"候補者":候補者.split(",") , "投票結果":投票結果.split(",")}

候補者と投票結果を辞書に格納する = {"候補者": list(set(候補者と投票結果["投票結果"])), "投票結果": [i for i in 投票結果["投票結果"] if i in候補者["候補者"]]}}

投票数をカウントする = {候補者["候補者"][i]: 投票結果["投票結果"].count(i) for i in候補者["候補者"]}

print("投票結果:")
for i in 投票結果["候補者"]:
    print(f"{i}: {投票数をカウントする[i]}")
